// Four-cell ramps join ground to a full ledge's authored upper floor.
export const RAMP_RUN=4,RAMP_RISE=2;
export const RAMP_DIRECTIONS={north:[0,-1],east:[1,0],south:[0,1],west:[-1,0]};
export const RAMP_PROPS=Object.fromEntries(['grass','sand','road','concrete'].flatMap(surface=>Object.entries(RAMP_DIRECTIONS).map(([direction,[dx]])=>['ramp-'+surface+'-'+direction,{w:dx?4:1,h:dx?1:4,solid:false,cover:0,ramp:true}])));
export const isRamp=p=>!!RAMP_PROPS[p?.kind];
export function rampInfo(p){if(!isRamp(p))return null;const [_,surface,direction]=p.kind.split('-'),[dx,dy]=RAMP_DIRECTIONS[direction],z=p.z||0,low={x:p.x+(dx<0?3:0),y:p.y+(dy<0?3:0),z};return {p,surface,direction,dx,dy,z,low,high:{x:low.x+dx*3,y:low.y+dy*3,z},entry:{x:low.x-dx,y:low.y-dy,z},exit:{x:low.x+dx*4,y:low.y+dy*4,z:z+1}};}
export function rampAt(map,q){return (map.props||[]).find(p=>isRamp(p)&&(p.z||0)===(q.z||0)&&q.x>=p.x-.5&&q.y>=p.y-.5&&q.x<p.x+RAMP_PROPS[p.kind].w-.5&&q.y<p.y+RAMP_PROPS[p.kind].h-.5);}
export function rampHeight(p,q){const r=rampInfo(p);return Math.max(0,Math.min(2,((q.x-r.low.x)*r.dx+(q.y-r.low.y)*r.dy+.5)*.5));}
export function rampSupportAt(map,q){const p=rampAt(map,q);return p?{level:p.z||0,height:rampHeight(p,q)}:null;}
export function rampMoveAllowed(map,a,b){for(const q of [a,b]){const p=rampAt(map,q);if(!p)continue;const r=rampInfo(p);if((a.z||0)!==(b.z||0))continue;if(r.dx?a.y!==b.y:a.x!==b.x){const pa=rampAt(map,a),pb=rampAt(map,b);if(!pa||!pb||rampInfo(pa).direction!==rampInfo(pb).direction||Math.abs(rampHeight(pa,a)-rampHeight(pb,b))>1e-6)return false;continue;}const other=q===a?b:a;if(!rampAt(map,other)&&!(other.x===r.entry.x&&other.y===r.entry.y))return false;}return true;}
export function rampLinks(map,q){const links=[];for(const p of map.props||[]){if(!isRamp(p))continue;const r=rampInfo(p),same=(a,b)=>a.x===b.x&&a.y===b.y&&(a.z||0)===(b.z||0);if(same(q,r.high))links.push({...r.exit,cost:1,kind:'ramp'});if(same(q,r.exit))links.push({...r.high,cost:1,kind:'ramp'});}return links;}
export function rampErrors(map){const errors=[],terrain=q=>(q.z?map.upper?.[q.z-1]?.[q.x+','+q.y]:(map.terrain||map.map)?.[q.y]?.[q.x]);for(const p of map.props||[]){if(!isRamp(p))continue;const r=rampInfo(p);if(p.rotated)errors.push('Choose a cardinal ramp direction instead of rotating the prop.');if(r.z>=2)errors.push('Ramps need an upper level.');if(!terrain(r.entry)||['void','water'].includes(terrain(r.entry)))errors.push('Ramp needs a walkable lower approach.');if(!terrain(r.exit)||['void','water'].includes(terrain(r.exit)))errors.push('Ramp needs an upper landing floor.');if(!(map.props||[]).some(c=>c.kind==='cliff-ledge'&&(c.cliffMask??15)===15&&c.x===r.exit.x&&c.y===r.exit.y&&(c.z||0)===r.z))errors.push('Ramp upper landing needs a full ledge tile.');}return errors;}
// Exact intersection against the sloping solid, using convex half-space clipping.
export function rampRayHit(props,origin,direction,limit,spacing=3){let hit=null;for(const p of props||[]){if(!isRamp(p))continue;const r=rampInfo(p),rule=RAMP_PROPS[p.kind],base=r.z*spacing;let lo=0,hi=limit;const constraints=[[origin.x-(p.x-.5),direction.x],[(p.x+rule.w-.5)-origin.x,-direction.x],[origin.y-(p.y-.5),direction.y],[(p.y+rule.h-.5)-origin.y,-direction.y],[origin.h-base,direction.h],[base+.5*((origin.x-r.low.x)*r.dx+(origin.y-r.low.y)*r.dy+.5)-origin.h,.5*(direction.x*r.dx+direction.y*r.dy)-direction.h]];for(const [a,b]of constraints){if(Math.abs(b)<1e-9){if(a<0){hi=-1;break;}}else if(b>0)lo=Math.max(lo,-a/b);else hi=Math.min(hi,-a/b);}if(lo<=hi&&hi>1e-6&&lo<=limit)hit=hit===null?Math.max(1e-6,lo):Math.min(hit,Math.max(1e-6,lo));}return hit;}
